#!/usr/bin/env bash
# GENERATED by harness/scripts/generate.sh from harness/templates/guard.sh (variant: go). Do not edit; change the template and regenerate.
# PreToolUse guard: blocks delete / destructive git / package installs / secret access / guard tampering.
# Exit 2 = block the tool call; stderr is shown to Claude as the reason.
# ask() = require user confirmation (JSON permissionDecision "ask").
# Premise: runs inside a dev container; regex guards are best-effort, the container is the outer boundary.
set -u

block() {
  echo "Blocked by .claude/hooks/guard.sh: $1" >&2
  exit 2
}

ASK_REASON=""
ask() { [[ -z "$ASK_REASON" ]] && ASK_REASON="$1"; }

emit_ask_or_allow() {
  if [[ -n "$ASK_REASON" ]]; then
    jq -n --arg r "guard.sh: $ASK_REASON" \
      '{hookSpecificOutput:{hookEventName:"PreToolUse",permissionDecision:"ask",permissionDecisionReason:$r}}'
  fi
  exit 0
}

# Without jq: block only what cannot be inspected (Bash) and obvious .env access; allow the rest.
if ! command -v jq >/dev/null 2>&1; then
  IFS= read -r -d '' input || true
  # Pure bash regex (no external commands) so a missing grep cannot make this pass silently.
  env_re='\.env(\.[A-Za-z0-9_-]+)*"'
  bash_re='"tool_name"[[:space:]]*:[[:space:]]*"Bash"'
  [[ "${input//.env.example/}" =~ $env_re ]] && block "possible .env access (jq not installed)"
  [[ "$input" =~ $bash_re ]] && block "jq not installed; Bash commands cannot be inspected"
  exit 0
fi

input="$(cat)"
# Fail closed: unparsable input is blocked instead of silently allowed.
tool="$(jq -er '.tool_name' <<<"$input" 2>/dev/null)" || block "failed to parse hook input"

# Matches .env, .env.local, .env.production, ... but not .env.example / process.env / .envrc
ENV_RE='(^|[^A-Za-z0-9_])\.env(\.[A-Za-z0-9_.-]+)?($|[^A-Za-z0-9_.-])'
# Unquoted glob tricks that can expand to .env: .e?v  .en*  .*  .[e]nv  .{env,x}
ENV_GLOB_RE='(^|[^A-Za-z0-9_.])\.(e[A-Za-z]*)?[*?[{]'
# Credentials outside the repo
SECRET_RE='(^|[^A-Za-z0-9_])(\.ssh/|\.ssh$|\.config/gh|\.git-credentials|\.claude/\.credentials|\.netrc|\.aws/|\.docker/config\.json)'
# Guard / git-hook files whose modification would disable or bypass this guard
PROTECT_RE='(^|/)\.claude/(settings(\.local)?\.json|hooks(/|$))|(^|/)\.git/(hooks(/|$)|config$)'

is_env_path() {
  local base
  base="$(basename -- "$1")"
  [[ "$base" == ".env.example" ]] && return 1
  [[ "$base" =~ ^\.env(\..+)?$ ]]
}
is_secret_path()    { [[ "$1" =~ $SECRET_RE ]]; }
is_protected_path() { [[ "$1" =~ $PROTECT_RE ]]; }

# Message arguments (git commit -m, gh pr create --title/--body) are literal text, not commands.
# Single-quoted ones are always literal; double-quoted ones only without $( or backticks.
strip_messages() {
  sed -E "s/(^|[[:space:]])(-m|--message|--title|--body)([[:space:]]+|=)'[^']*'/\\1\\2 MSG/g" <<<"$1" |
    sed -E 's/(^|[[:space:]])(-m|--message|--title|--body)([[:space:]]+|=)"[^"$`]*"/\1\2 MSG/g'
}
# Quoted strings do not undergo glob expansion (double quotes only when free of $( and backticks).
strip_quoted() {
  sed -E "s/'[^']*'//g" <<<"$1" | sed -E 's/"[^"$`]*"//g'
}

case "$tool" in
  Bash)
    raw="$(jq -r '.tool_input.command // ""' <<<"$input")"
    cmd="$(strip_messages "$raw")"
    # Command boundary: start, separators, quotes (bash -c "..."), '/' (/bin/rm), '\' (\rm), '{'
    S="(^|[;&|(\`\"'{[:space:]/\\\\])"
    m() { grep -qE -- "$1" <<<"$cmd"; }

    # --- delete (irreversible) ---
    m "${S}(rm|rmdir|unlink|shred|truncate|srm|wipe)([[:space:]]|$)" && block "delete command (rm/rmdir/unlink/shred/truncate)"
    m "${S}find[[:space:]].*-delete" && block "find -delete"
    m "${S}mv[[:space:]].*/dev/null" && block "mv to /dev/null"
    m "(shutil\.rmtree|os\.(remove|unlink|rmdir|removedirs)|\.unlink\(|unlinkSync|rmSync|rmdirSync|fs\.rm\(|FileUtils\.rm|File\.delete)" && block "file deletion via scripting language"

    # --- destructive git (irreversible) ---
    m "${S}git[[:space:]]+(rm|clean)([[:space:]]|$)" && block "git rm / git clean"
    m "${S}git[[:space:]]+branch[[:space:]]+.*(-D|--delete)" && block "git branch delete"
    m "${S}git[[:space:]]+push([[:space:]].*)?[[:space:]](--force(-with-lease|-if-includes)?|--delete|--mirror|--prune|-[A-Za-z]*[fd][A-Za-z]*)([[:space:]]|=|$)" && block "git push --force / --delete / --mirror"
    m "${S}git[[:space:]]+push([[:space:]]+[^[:space:]]+)*[[:space:]]+[+:][^[:space:]]" && block "git push with +refspec (force) or :refspec (delete)"
    m "${S}git[[:space:]]+(filter-branch|filter-repo|update-ref[[:space:]]+-d|reflog[[:space:]]+(expire|delete))" && block "git history rewrite / ref deletion"
    m "${S}git[[:space:]]+gc([[:space:]].*)?--prune" && block "git gc --prune"

    # --- guard tampering (git config that runs arbitrary code, protected files, container firewall) ---
    m "${S}git[[:space:]]+(.*[[:space:]])?(config|-c)[[:space:]=].*(core\.(hooksPath|fsmonitor|sshCommand|pager|editor|askPass)|alias\.|credential\.|include\.|includeIf\.)" && block "git config that can execute arbitrary commands"
    m "GIT_(CONFIG_(COUNT|KEY_|VALUE_|PARAMETERS)|SSH_COMMAND|EXEC_PATH|ASKPASS)" && block "git env override"
    m "\.claude/(settings(\.local)?\.json|hooks)|\.git/(hooks|config)" && block "access to protected guard / git hook files"
    m "${S}(sudo|su|doas|iptables|ip6tables|iptables-restore|ip6tables-restore|ipset|nft)([[:space:]]|$)" && block "privilege escalation / container firewall command"

    # --- remote script execution ---
    m "(curl|wget)[^|]*\|[[:space:]]*((ba|z|da|k)?sh|python3?|node|perl|ruby)([[:space:]]|$)" && block "pipe remote script to interpreter"
    m "<\([[:space:]]*(curl|wget)|\\\$\([[:space:]]*(curl|wget)" && block "execute remote script via process/command substitution"

    # --- packages (any language; managers defined in harness/lang.json) ---
    # Installing exactly what the project's lockfile pins = ask.
    # Adding deps, one-shot remote execution, global/system installs,
    # or a manager whose lockfile is absent / language not enabled = block.
    m "${S}(npm|pnpm|yarn|bun)[[:space:]](.*[[:space:]])?(-g|--global)([[:space:]]|=|$)" && block "global package install"
    m "${S}yarn[[:space:]]+global([[:space:]]|$)" && block "yarn global"
    m "${S}(npx|pnpx|pnx|bunx|uvx)([[:space:]]|$)" && block "one-shot remote package execution (npx/bunx/uvx)"
    m "${S}(pnpm|yarn)[[:space:]]+dlx([[:space:]]|$)|${S}npm[[:space:]]+exec([[:space:]]|$)|${S}pipx[[:space:]]+run([[:space:]]|$)|${S}go[[:space:]]+run[[:space:]]+[^[:space:]]+@" && block "one-shot remote package execution (dlx/npm exec/pipx run/go run pkg@ver)"
    m "${S}(cargo|go|pipx)[[:space:]]+install([[:space:]]|$)|${S}uv[[:space:]]+tool[[:space:]]+install" && block "global tool install"
    m "${S}(apt|apt-get|yum|dnf|apk)[[:space:]]+(install|add)" && block "system package install"
    m "${S}brew[[:space:]]+install" && block "brew install"

    proj="${CLAUDE_PROJECT_DIR:-}"
    cwd="$(jq -r '.cwd // ""' <<<"$input")"
    has_lock() {
      local d f
      for d in "$cwd" "$proj"; do
        [[ -n "$d" ]] || continue
        for f in "$@"; do [[ -e "$d/$f" ]] && return 0; done
      done
      return 1
    }
    F='([[:space:]]+-[^[:space:]]+)*[[:space:]]*($|[;&|)])'   # only flags may follow
    rest="$cmd"; lock_used=""
    # lock_ok REGEX LOCKFILE... : if the lockfile exists, strip matching lockfile installs from $rest
    lock_ok() {
      local re="$1"; shift
      has_lock "$@" || return 0
      grep -qE -- "${S}${re}${F}" <<<"$rest" || return 0
      rest="$(sed -E "s#${S}${re}${F}#\\1 #g" <<<"$rest")"
      lock_used="${lock_used:+$lock_used, }$1"
    }
    lock_ok 'go[[:space:]]+mod[[:space:]]+download' go.sum

    PKG_RE="${S}(bun[[:space:]]+add|bun[[:space:]]+i|bun[[:space:]]+install|bun[[:space:]]+update|cargo[[:space:]]+add|cargo[[:space:]]+fetch|go[[:space:]]+get|go[[:space:]]+mod[[:space:]]+download|npm[[:space:]]+add|npm[[:space:]]+ci|npm[[:space:]]+i|npm[[:space:]]+install|npm[[:space:]]+update|pip[[:space:]]+install|pip[[:space:]]+install[[:space:]]+-r[[:space:]]+requirements\.txt|pip3[[:space:]]+install|pip3[[:space:]]+install[[:space:]]+-r[[:space:]]+requirements\.txt|pipenv[[:space:]]+install|pipenv[[:space:]]+sync|pnpm[[:space:]]+add|pnpm[[:space:]]+i|pnpm[[:space:]]+install|pnpm[[:space:]]+up|pnpm[[:space:]]+update|pnpm[[:space:]]+upgrade|poetry[[:space:]]+add|poetry[[:space:]]+install|poetry[[:space:]]+sync|uv[[:space:]]+add|uv[[:space:]]+pip[[:space:]]+install|uv[[:space:]]+sync|yarn[[:space:]]+add|yarn[[:space:]]+install|yarn[[:space:]]+up|yarn[[:space:]]+upgrade)([[:space:]]|$|[;&|)])"
    PKG_BARE_RE="${S}(yarn)${F}"
    if grep -qE -- "$PKG_RE" <<<"$rest" || grep -qE -- "$PKG_BARE_RE" <<<"$rest"; then
      block "package install not pinned by a lockfile, language not enabled, or adds new dependencies (install manually if needed)"
    fi
    [[ -n "$lock_used" ]] && ask "installs dependencies pinned by lockfile ($lock_used)"

    # --- destructive GitHub operations ---
    m "${S}gh[[:space:]]+(repo[[:space:]]+(delete|archive|rename|edit)|(release|issue|label|cache|run|gist)[[:space:]]+delete|secret|variable|ssh-key|gpg-key|auth[[:space:]]+(token|logout|refresh|setup-git))" && block "destructive / credential gh command"
    m "${S}gh[[:space:]]+api([[:space:]].*)?(-X|--method)[[:space:]=]*DELETE" && block "gh api DELETE"

    # --- secrets ---
    stripped="${cmd//.env.example/}"
    grep -qE -- "$ENV_RE" <<<"$stripped" && block "command references a .env file"
    grep -qE -- "$ENV_GLOB_RE" <<<"$(strip_quoted "$stripped")" && block "glob that may expand to a .env file"
    m "$SECRET_RE" && block "command references credential files"

    # --- recoverable but risky: require confirmation ---
    m "${S}git[[:space:]]+reset([[:space:]].*)?[[:space:]]--(hard|merge|keep)" && ask "git reset --hard discards local changes"
    m "${S}git[[:space:]]+checkout([[:space:]].*)?[[:space:]](--|\.)([[:space:]]|$)" && ask "git checkout -- / . discards local changes"
    m "${S}git[[:space:]]+restore([[:space:]]|$)" && ask "git restore discards local changes"
    m "${S}git[[:space:]]+stash[[:space:]]+(drop|clear)" && ask "git stash drop/clear"
    emit_ask_or_allow
    ;;

  Read|Edit|Write|NotebookEdit|Grep|Glob)
    for key in file_path notebook_path path; do
      p="$(jq -r ".tool_input.${key} // \"\"" <<<"$input")"
      [[ -z "$p" ]] && continue
      is_env_path "$p"    && block "access to .env file ($p)"
      is_secret_path "$p" && block "access to credential file ($p)"
      if [[ "$tool" == "Edit" || "$tool" == "Write" || "$tool" == "NotebookEdit" ]] && is_protected_path "$p"; then
        block "modifying protected guard / git hook file ($p) — edit it manually"
      fi
    done
    ;;
esac

exit 0
